static final long MOD = 10000000007L;

public long stepPerms(int n) {
    if (n == 0 || n == 1) return 1;
    if (n == 2) return 2;
    long a = 1, b = 1, c = 2;  // ways(0), ways(1), ways(2)
    for (int i = 3; i <= n; i++) {
        long next = (a + b + c) % MOD;
        a = b; b = c; c = next;
    }
    return c;
}

